Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\js\navbar.js", "content": "/*
 * Navbar resizing and the position indicator.
 */
import { activeSectionIndex } from './lib/geometry.js';

const SCROLLED_CLASS = 'is-scrolled';
const ACTIVE_CLASS = 'is-active';
const SHRINK_AFTER_PX = 40;
const PAGE_BOTTOM_TOLERANCE_PX = 2;

export function initNavbar() {
  const navbar = document.querySelector('[data-navbar]');
  const links = Array.from(document.querySelectorAll('[data-nav-link]'));
  const sections = links.map((link) => document.querySelector(link.getAttribute('href')));
  if (!navbar || links.length === 0 || sections.includes(null)) {
    return;
  }

  let activeIndex = -1;
  let frameRequested = false;

  const setActive = (index) => {
    if (index === activeIndex) {
      return;
    }
    links.forEach((link, linkIndex) => {
      const isActive = linkIndex === index;
      link.classList.toggle(ACTIVE_CLASS, isActive);
      if (isActive) {
        link.setAttribute('aria-current', 'true');
      } else {
        link.removeAttribute('aria-current');
      }
    });
    activeIndex = index;
  };

  const update = () => {
    frameRequested = false;
    navbar.classList.toggle(SCROLLED_CLASS, window.scrollY > SHRINK_AFTER_PX);

    // Measure the navbar as it is right now: it may be mid-resize.
    const navBottom = navbar.getBoundingClientRect().bottom;
    const rects = sections.map((section) => section.getBoundingClientRect());
    const pageBottom = document.documentElement.scrollHeight - PAGE_BOTTOM_TOLERANCE_PX;
    const atBottom = window.scrollY + window.innerHeight >= pageBottom;
    setActive(activeSectionIndex(rects, navBottom, atBottom));
  };

  // Scroll and resize fire far more often than the screen repaints, so all of
  // them collapse into one measurement per animation frame.
  const requestUpdate = () => {
    if (!frameRequested) {
      frameRequested = true;
      window.requestAnimationFrame(update);
    }
  };

  window.addEventListener('scroll', requestUpdate, { passive: true });
  window.addEventListener('resize', requestUpdate);
  // The navbar's bottom edge keeps moving after the last scroll event while
  // its height transition finishes; measure once more when it settles.
  navbar.addEventListener('transitionend', (event) => {
    if (event.target === navbar && event.propertyName === 'height') {
      requestUpdate();
    }
  });

  update();
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\js\scroll.js", "content": "/*
 * Smooth scrolling for in-page links, animated by hand with
 * requestAnimationFrame. CSS scroll-behavior is deliberately left unset so the
 * two never compound.
 */
import { scrollTargetY, scrollDuration, easeInOutCubic } from './lib/geometry.js';

const INTERRUPT_EVENTS = ['wheel', 'touchstart', 'keydown'];

export function initSmoothScroll() {
  const links = Array.from(document.querySelectorAll('[data-scroll]'));
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let frameId = 0;

  // The navbar is in its small state everywhere except the very top, so the
  // small height is the offset every landing needs. It is defined once, in
  // the SCSS tokens, and read back here.
  const smallNavHeight = () => {
    const value = getComputedStyle(document.documentElement).getPropertyValue('--nav-h-small');
    return parseFloat(value) || 0;
  };

  const stop = () => {
    if (frameId) {
      window.cancelAnimationFrame(frameId);
      frameId = 0;
    }
    INTERRUPT_EVENTS.forEach((name) => window.removeEventListener(name, stop));
  };

  const scrollToSection = (section) => {
    stop();

    const startY = window.scrollY;
    const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
    const sectionTop = section.getBoundingClientRect().top + startY;
    const endY = scrollTargetY(sectionTop, smallNavHeight(), maxScroll);
    const distance = endY - startY;

    if (reducedMotion.matches || distance === 0) {
      window.scrollTo(0, endY);
      return;
    }

    const duration = scrollDuration(distance);
    const startTime = performance.now();

    const step = (now) => {
      const progress = (now - startTime) / duration;
      window.scrollTo(0, startY + distance * easeInOutCubic(progress));
      if (progress < 1) {
        frameId = window.requestAnimationFrame(step);
      } else {
        stop();
      }
    };

    // The visitor always wins: any scroll input of their own ends the animation.
    INTERRUPT_EVENTS.forEach((name) => window.addEventListener(name, stop, { passive: true }));
    frameId = window.requestAnimationFrame(step);
  };

  links.forEach((link) => {
    const section = document.querySelector(link.getAttribute('href'));
    if (!section) {
      return;
    }
    link.addEventListener('click', (event) => {
      event.preventDefault();
      scrollToSection(section);
      window.history.replaceState(null, '', link.getAttribute('href'));
    });
  });
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\js\main.js", "content": "/*
 * Entry point: wires each behavior module to the page once the DOM is ready.
 */
import { initNavbar } from './navbar.js';
import { initSmoothScroll } from './scroll.js';

const init = () => {
  initNavbar();
  initSmoothScroll();
};

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
"}

