Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\js\carousel.js", "content": "/*
 * Project carousel: side arrows, wrap-around, and a slide indicator.
 *
 * The track is moved by CSS alone. This module only records the current slide
 * in a data attribute, and _carousel.scss maps each index to a transform, so
 * no inline styles are ever written.
 */
import { wrapIndex } from './lib/geometry.js';

// Longer than the CSS transition; releases the lock if transitionend is
// never delivered (for example when the tab is hidden mid-slide).
const UNLOCK_FALLBACK_MS = 700;

function initCarousel(root) {
  const track = root.querySelector('[data-carousel-track]');
  const slides = Array.from(root.querySelectorAll('[data-carousel-slide]'));
  const previous = root.querySelector('[data-carousel-prev]');
  const next = root.querySelector('[data-carousel-next]');
  const status = root.querySelector('[data-carousel-status]');
  if (!track || slides.length === 0 || !previous || !next) {
    return;
  }

  let current = 0;
  let locked = false;
  let fallbackTimer = 0;

  const unlock = () => {
    locked = false;
    window.clearTimeout(fallbackTimer);
  };

  const render = () => {
    track.dataset.index = String(current);
    slides.forEach((slide, index) => {
      // Off-screen slides leave the tab order and the accessibility tree.
      slide.inert = index !== current;
    });
    if (status) {
      status.textContent = `Slide ${current + 1} of ${slides.length}`;
    }
  };

  const go = (step) => {
    // Clicks that arrive mid-transition are ignored rather than queued.
    if (locked) {
      return;
    }
    const target = wrapIndex(current + step, slides.length);
    if (target === current) {
      return;
    }
    locked = true;
    fallbackTimer = window.setTimeout(unlock, UNLOCK_FALLBACK_MS);
    current = target;
    render();
  };

  track.addEventListener('transitionend', (event) => {
    if (event.target === track && event.propertyName === 'transform') {
      unlock();
    }
  });
  previous.addEventListener('click', () => go(-1));
  next.addEventListener('click', () => go(1));

  render();
}

export function initCarousels() {
  document.querySelectorAll('[data-carousel]').forEach(initCarousel);
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp1\src\js\modal.js", "content": "/*
 * Project detail modals, built on the native <dialog> element.
 *
 * showModal() gives us the focus trap, the inert page behind, and focus
 * return on close. This module adds what <dialog> lacks: closing on a
 * backdrop click, locking page scroll, and an exit animation.
 */
const SCROLL_LOCK_CLASS = 'is-scroll-locked';
const CLOSING_CLASS = 'is-closing';
// Longer than the CSS exit animation; closes anyway if animationend is lost.
const CLOSE_FALLBACK_MS = 400;

function open(dialog) {
  dialog.showModal();
  document.documentElement.classList.add(SCROLL_LOCK_CLASS);
  const closeButton = dialog.querySelector('[data-modal-close]');
  if (closeButton) {
    closeButton.focus();
  }
}

function requestClose(dialog) {
  if (dialog.classList.contains(CLOSING_CLASS)) {
    return;
  }

  let finished = false;
  const finish = () => {
    if (finished) {
      return;
    }
    finished = true;
    dialog.classList.remove(CLOSING_CLASS);
    dialog.close();
  };

  dialog.classList.add(CLOSING_CLASS);
  dialog.addEventListener('animationend', (event) => {
    // The backdrop's own animation reports through the dialog too; wait for
    // the dialog's.
    if (event.target === dialog && !event.pseudoElement) {
      finish();
    }
  }, { once: false });
  window.setTimeout(finish, CLOSE_FALLBACK_MS);
}

function bind(dialog) {
  // Escape fires "cancel" and would close instantly; route it through the
  // same animated close as every other path.
  dialog.addEventListener('cancel', (event) => {
    event.preventDefault();
    requestClose(dialog);
  });

  // The panel fills the dialog box, so a click whose target is the dialog
  // itself can only have landed on the backdrop.
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) {
      requestClose(dialog);
    }
  });

  dialog.querySelectorAll('[data-modal-close]').forEach((button) => {
    button.addEventListener('click', () => requestClose(dialog));
  });

  // Every close path ends here, so the scroll lock can never be left behind.
  dialog.addEventListener('close', () => {
    document.documentElement.classList.remove(SCROLL_LOCK_CLASS);
  });
}

export function initModals() {
  document.querySelectorAll('[data-modal-open]').forEach((opener) => {
    const dialog = document.getElementById(opener.dataset.modalOpen);
    if (!dialog || typeof dialog.showModal !== 'function') {
      return;
    }
    opener.addEventListener('click', () => open(dialog));
  });

  document.querySelectorAll('dialog.modal').forEach(bind);
}
"}

