1	/*
2	 * Project detail modals, built on the native <dialog> element.
3	 *
4	 * showModal() gives us the focus trap, the inert page behind, and focus
5	 * return on close. This module adds what <dialog> lacks: closing on a
6	 * backdrop click, locking page scroll, and an exit animation.
7	 */
8	const SCROLL_LOCK_CLASS = 'is-scroll-locked';
9	const CLOSING_CLASS = 'is-closing';
10	// Longer than the CSS exit animation; closes anyway if animationend is lost.
11	const CLOSE_FALLBACK_MS = 400;
12	
13	function open(dialog) {
14	  dialog.showModal();
15	  document.documentElement.classList.add(SCROLL_LOCK_CLASS);
16	  const closeButton = dialog.querySelector('[data-modal-close]');
17	  if (closeButton) {
18	    closeButton.focus();
19	  }
20	}
21	
22	function requestClose(dialog) {
23	  if (dialog.classList.contains(CLOSING_CLASS)) {
24	    return;
25	  }
26	
27	  let fallbackTimer = 0;
28	
29	  // The dialog's exit animation and its backdrop's run for the same time, so
30	  // whichever reports first is the signal to close.
31	  function finish(event) {
32	    if (event && event.target !== dialog) {
33	      return;
34	    }
35	    dialog.removeEventListener('animationend', finish);
36	    window.clearTimeout(fallbackTimer);
37	    dialog.classList.remove(CLOSING_CLASS);
38	    dialog.close();
39	  }
40	
41	  dialog.classList.add(CLOSING_CLASS);
42	  dialog.addEventListener('animationend', finish);
43	  fallbackTimer = window.setTimeout(finish, CLOSE_FALLBACK_MS);
44	}
45	
46	function bind(dialog) {
47	  // Escape fires "cancel" and would close instantly; route it through the
48	  // same animated close as every other path.
49	  dialog.addEventListener('cancel', (event) => {
50	    event.preventDefault();
51	    requestClose(dialog);
52	  });
53	
54	  // The panel fills the dialog box, so a click whose target is the dialog
55	  // itself can only have landed on the backdrop.
56	  dialog.addEventListener('click', (event) => {
57	    if (event.target === dialog) {
58	      requestClose(dialog);
59	    }
60	  });
61	
62	  dialog.querySelectorAll('[data-modal-close]').forEach((button) => {
63	    button.addEventListener('click', () => requestClose(dialog));
64	  });
65	
66	  // Every close path ends here, so the scroll lock can never be left behind.
67	  dialog.addEventListener('close', () => {
68	    document.documentElement.classList.remove(SCROLL_LOCK_CLASS);
69	  });
70	}
71	
72	export function initModals() {
73	  document.querySelectorAll('[data-modal-open]').forEach((opener) => {
74	    const dialog = document.getElementById(opener.dataset.modalOpen);
75	    if (!dialog || typeof dialog.showModal !== 'function') {
76	      return;
77	    }
78	    opener.addEventListener('click', () => open(dialog));
79	  });
80	
81	  document.querySelectorAll('dialog.modal').forEach(bind);
82	}
