1	/*
2	 * Pure layout math shared by the behavior modules. Nothing here touches the
3	 * DOM, so it is unit tested directly in tests/geometry.test.mjs.
4	 */
5	
6	const EDGE_TOLERANCE = 1;
7	const MIN_SCROLL_MS = 400;
8	const MAX_SCROLL_MS = 900;
9	const MS_PER_PIXEL = 0.25;
10	
11	/**
12	 * Index of the section lying directly under the navbar's bottom edge.
13	 *
14	 * @param {{top: number}[]} rects section tops in viewport coordinates, in page order
15	 * @param {number} navBottom the navbar's bottom edge in viewport coordinates
16	 * @param {boolean} atBottom whether the page is scrolled to its end
17	 * @returns {number} the active index, or -1 when there are no sections
18	 */
19	export function activeSectionIndex(rects, navBottom, atBottom) {
20	  if (rects.length === 0) {
21	    return -1;
22	  }
23	  // A short last section can never reach the navbar, so the end of the page
24	  // always belongs to it.
25	  if (atBottom) {
26	    return rects.length - 1;
27	  }
28	  // The last section whose top has reached the edge wins. Searching from the
29	  // end matters at a boundary: the previous section's bottom and the next
30	  // section's top are both within tolerance there, and the next one is current.
31	  const edge = navBottom + EDGE_TOLERANCE;
32	  for (let index = rects.length - 1; index > 0; index -= 1) {
33	    if (rects[index].top <= edge) {
34	      return index;
35	    }
36	  }
37	  return 0;
38	}
39	
40	/**
41	 * Scroll position that lands a section's top flush under the small navbar.
42	 */
43	export function scrollTargetY(sectionTop, smallNavHeight, maxScroll) {
44	  return Math.min(Math.max(sectionTop - smallNavHeight, 0), maxScroll);
45	}
46	
47	/**
48	 * Animation length for a scroll of the given distance: longer trips take
49	 * longer, within fixed bounds so no trip feels instant or sluggish.
50	 */
51	export function scrollDuration(distance) {
52	  const scaled = Math.abs(distance) * MS_PER_PIXEL;
53	  return Math.min(Math.max(scaled, MIN_SCROLL_MS), MAX_SCROLL_MS);
54	}
55	
56	/**
57	 * Cubic ease-in-out over progress 0..1; out-of-range progress is clamped.
58	 */
59	export function easeInOutCubic(progress) {
60	  const t = Math.min(Math.max(progress, 0), 1);
61	  return t < 0.5 ? 4 * t * t * t : 1 - ((-2 * t + 2) ** 3) / 2;
62	}
63	
64	/**
65	 * Wraps an index into 0..count-1 so stepping past either end of a list comes
66	 * back around. Returns 0 when the list is empty.
67	 */
68	export function wrapIndex(index, count) {
69	  if (count <= 0) {
70	    return 0;
71	  }
72	  return ((index % count) + count) % count;
73	}
