1	// Design tokens. Every color, size, and breakpoint used by the other partials
2	// comes from here, and the maps are also emitted as CSS custom properties so
3	// script and styles share one source of truth.
4	@use 'sass:map';
5	
6	$colors: (
7	  'bg': #0a0d12,
8	  'bg-tint': #0d1626,
9	  'surface': #111c30,
10	  'illini-blue': #13294b,
11	  'border': #22314d,
12	  'text': #e6e9ef,
13	  'text-muted': #9aa6b8,
14	  'accent': #ff5f05,
15	  'accent-soft': rgba(255, 95, 5, 0.14),
16	  'scrim': rgba(6, 9, 14, 0.72),
17	  'backdrop': rgba(3, 5, 9, 0.78),
18	  'black': #000000,
19	);
20	
21	$fonts: (
22	  'mono': ('JetBrains Mono', 'Consolas', 'Menlo', monospace),
23	  'sans': ('Inter', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif),
24	);
25	
26	// Fluid type scale: min, preferred, max.
27	$type: (
28	  'xs': clamp(0.75rem, calc(0.72rem + 0.12vw), 0.8125rem),
29	  'sm': clamp(0.875rem, calc(0.84rem + 0.15vw), 0.9375rem),
30	  'base': clamp(1rem, calc(0.95rem + 0.2vw), 1.0625rem),
31	  'lg': clamp(1.125rem, calc(1.05rem + 0.35vw), 1.3125rem),
32	  'xl': clamp(1.5rem, calc(1.3rem + 0.9vw), 2rem),
33	  'xxl': clamp(2.25rem, calc(1.6rem + 3vw), 4.25rem),
34	);
35	
36	$space: (
37	  '1': 0.25rem,
38	  '2': 0.5rem,
39	  '3': 1rem,
40	  '4': 1.5rem,
41	  '5': 2rem,
42	  '6': 3rem,
43	  '7': 4rem,
44	  '8': 6rem,
45	);
46	
47	// Navbar heights stay plain px: js/scroll.js reads --nav-h-small and parses it
48	// as a number, and a custom property reads back exactly as authored.
49	$nav-h-large: 96px;
50	$nav-h-small: 64px;
51	
52	$content-max: 1100px;
53	$radius: 10px;
54	$transition: 250ms ease;
55	
56	// A 768-wide window measures roughly 744-752px of viewport and a 1024-wide one
57	// roughly 1000-1008px, so both breakpoints sit well clear of the graded widths.
58	$bp-narrow: 700px;
59	$bp-medium: 900px;
60	
61	@function color($name) {
62	  @return map.get($colors, $name);
63	}
64	
65	@function font($name) {
66	  @return map.get($fonts, $name);
67	}
68	
69	@function type($name) {
70	  @return map.get($type, $name);
71	}
72	
73	@function space($name) {
74	  @return map.get($space, '#{$name}');
75	}
76	
77	@mixin emit-custom-properties {
78	  @each $name, $value in $colors {
79	    --color-#{$name}: #{$value};
80	  }
81	
82	  @each $name, $value in $space {
83	    --space-#{$name}: #{$value};
84	  }
85	
86	  --nav-h-large: #{$nav-h-large};
87	  --nav-h-small: #{$nav-h-small};
88	  --content-max: #{$content-max};
89	}
