2309	+/*
2310	+ * Project carousel: side arrows, wrap-around, and a slide indicator.
2311	+ *
2312	+ * The track is moved by CSS alone. This module only records the current slide
2313	+ * in a data attribute, and _carousel.scss maps each index to a transform, so
2314	+ * no inline styles are ever written.
2315	+ */
2316	+import { wrapIndex } from './lib/geometry.js';
2317	+
2318	+// Longer than the CSS transition; releases the lock if transitionend is
2319	+// never delivered (for example when the tab is hidden mid-slide).
2320	+const UNLOCK_FALLBACK_MS = 700;
2321	+
2322	+function initCarousel(root) {
2323	+  const track = root.querySelector('[data-carousel-track]');
2324	+  const slides = Array.from(root.querySelectorAll('[data-carousel-slide]'));
2325	+  const previous = root.querySelector('[data-carousel-prev]');
2326	+  const next = root.querySelector('[data-carousel-next]');
2327	+  const status = root.querySelector('[data-carousel-status]');
2328	+  if (!track || slides.length === 0 || !previous || !next) {
2329	+    return;
2330	+  }
2331	+
2332	+  let current = 0;
2333	+  let locked = false;
2334	+  let fallbackTimer = 0;
2335	+
2336	+  const unlock = () => {
2337	+    locked = false;
2338	+    window.clearTimeout(fallbackTimer);
2339	+  };
2340	+
2341	+  const render = () => {
2342	+    track.dataset.index = String(current);
2343	+    slides.forEach((slide, index) => {
2344	+      // Off-screen slides leave the tab order and the accessibility tree.
2345	+      slide.inert = index !== current;
2346	+    });
2347	+    if (status) {
2348	+      status.textContent = `Slide ${current + 1} of ${slides.length}`;
2349	+    }
2350	+  };
2351	+
2352	+  const go = (step) => {
2353	+    // Clicks that arrive mid-transition are ignored rather than queued.
2354	+    if (locked) {
2355	+      return;
2356	+    }
2357	+    const target = wrapIndex(current + step, slides.length);
2358	+    if (target === current) {
2359	+      return;
2360	+    }
2361	+    locked = true;
2362	+    fallbackTimer = window.setTimeout(unlock, UNLOCK_FALLBACK_MS);
2363	+    current = target;
2364	+    render();
2365	+  };
2366	+
2367	+  track.addEventListener('transitionend', (event) => {
2368	+    if (event.target === track && event.propertyName === 'transform') {
2369	+      unlock();
2370	+    }
2371	+  });
2372	+  previous.addEventListener('click', () => go(-1));
2373	+  next.addEventListener('click', () => go(1));
2374	+
2375	+  render();
2376	+}
2377	+
2378	+export function initCarousels() {
2379	+  document.querySelectorAll('[data-carousel]').forEach(initCarousel);
2380	+}
