/*
 * This is the main entry point for Webpack, the compiler & dependency loader.
 * All files that are necessary for your web page and need to be 'watched' for changes should be included here!
 */

// HTML Files
import './index.html';

// Stylesheets
import './css/main.scss';

// Scripts
import './js/main.js';
// Design tokens. Every color, size, and breakpoint used by the other partials
// comes from here. The few values that script or calc() needs at run time are
// also emitted as CSS custom properties, so they still have one source of truth.
@use 'sass:map';

$colors: (
  'bg': #0a0d12,
  'bg-tint': #0d1626,
  'surface': #111c30,
  'illini-blue': #13294b,
  'border': #22314d,
  'text': #e6e9ef,
  'text-muted': #9aa6b8,
  'accent': #ff5f05,
  'accent-soft': rgba(255, 95, 5, 0.14),
  'scrim': rgba(6, 9, 14, 0.72),
  'backdrop': rgba(3, 5, 9, 0.78),
  'black': #000000,
);

$fonts: (
  'mono': ('JetBrains Mono', 'Consolas', 'Menlo', monospace),
  'sans': ('Inter', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif),
);

// Fluid type scale: min, preferred, max.
$type: (
  'xs': clamp(0.75rem, calc(0.72rem + 0.12vw), 0.8125rem),
  'sm': clamp(0.875rem, calc(0.84rem + 0.15vw), 0.9375rem),
  'base': clamp(1rem, calc(0.95rem + 0.2vw), 1.0625rem),
  'lg': clamp(1.125rem, calc(1.05rem + 0.35vw), 1.3125rem),
  'xl': clamp(1.5rem, calc(1.3rem + 0.9vw), 2rem),
  'xxl': clamp(2.25rem, calc(1.6rem + 3vw), 4.25rem),
);

$space: (
  '1': 0.25rem,
  '2': 0.5rem,
  '3': 1rem,
  '4': 1.5rem,
  '5': 2rem,
  '6': 3rem,
  '7': 4rem,
  '8': 6rem,
);

// Navbar heights stay plain px: js/scroll.js reads --nav-h-small and parses it
// as a number, and a custom property reads back exactly as authored.
$nav-h-large: 96px;
$nav-h-small: 64px;

$content-max: 1100px;
$radius: 10px;
$transition: 250ms ease;

// A 768-wide window measures roughly 744-752px of viewport and a 1024-wide one
// roughly 1000-1008px, so both breakpoints sit well clear of the graded widths.
$bp-narrow: 700px;
$bp-medium: 900px;

@function color($name) {
  @return map.get($colors, $name);
}

@function font($name) {
  @return map.get($fonts, $name);
}

@function type($name) {
  @return map.get($type, $name);
}

@function space($name) {
  @return map.get($space, '#{$name}');
}

@mixin emit-custom-properties {
  --nav-h-large: #{$nav-h-large};
  --nav-h-small: #{$nav-h-small};
  --content-max: #{$content-max};
}
@use 'tokens' as *;
@use 'mixins' as *;

// Headroom, not dead code: slides can be added in index.html up to this count
// without touching the stylesheet.
$carousel-max-slides: 6;

// Arrows sit in their own side columns, so they are vertically centered beside
// the slides and can never cover a slide's text or its Details button.
.carousel {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: space(3);

  &__viewport {
    overflow: hidden;
    border-radius: $radius;
  }

  // js/carousel.js only records the current slide in data-index; each index
  // maps to a transform here, so the script never writes an inline style.
  &__track {
    display: flex;
    transition: transform 400ms ease;

    @for $index from 1 through $carousel-max-slides - 1 {
      &[data-index='#{$index}'] {
        transform: translateX(-100% * $index);
      }
    }
  }

  &__slide {
    flex: 0 0 100%;
    min-width: 0;
  }

  &__arrow {
    @include icon-button(52px);
    @include focus-ring;
    background-color: color('surface');
    color: color('text');
    font-size: 1.125rem;

    &:hover {
      border-color: color('accent');
      background-color: color('accent');
      color: color('bg');
      transform: scale(1.08);
    }
  }

  &__status {
    grid-column: 1 / -1;
    text-align: center;
    font-family: font('mono');
    font-size: type('sm');
    color: color('text-muted');
  }

  @include below($bp-narrow) {
    gap: space(2);

    &__arrow {
      width: 40px;
      height: 40px;
    }
  }
}

.project-card {
  @include card;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  align-items: center;
  gap: space(5);
