  }

  &__kind {
    @include label;
  }

  &__title {
    font-size: type('xl');
  }

  &__summary {
    color: color('text-muted');
  }

  // Narrower windows: stack the visual over the text and center it.
  @include below($bp-medium) {
    grid-template-columns: 1fr;
    gap: space(4);
    padding: space(4);
    text-align: center;

    &__visual {
      max-width: 420px;
      margin-inline: auto;
    }

    &__body {
      justify-items: center;
    }

    .tag-list {
      justify-content: center;
    }
  }
}
