html {
  // Keep the scrollbar gutter reserved so locking scroll for a modal does not
  // shift the page or the fixed navbar sideways.
  scrollbar-gutter: stable;
  -webkit-text-size-adjust: 100%;

  &.is-scroll-locked {
    overflow: hidden;
  }
}

body {
  margin: 0;
  background-color: color('bg');
  color: color('text');
  font-family: font('sans');
