:root {
  @include emit-custom-properties;
}

html {
  // Keep the scrollbar gutter reserved so locking scroll for a modal does not
  // shift the page or the fixed navbar sideways.
  scrollbar-gutter: stable;
  -webkit-text-size-adjust: 100%;

  &.is-scroll-locked {
    overflow: hidden;
  }
}

body {
  margin: 0;
  background-color: color('bg');
  color: color('text');
  font-family: font('sans');
  font-size: type('base');
---

  &__viewport {
    overflow: hidden;
    border-radius: $radius;
  }

  // js/carousel.js only records the current slide in data-index; each index
  // maps to a transform here, so the script never writes an inline style.
  &__track {
    display: flex;
    transition: transform 400ms ease;

    @for $index from 1 through $carousel-max-slides - 1 {
      &[data-index='#{$index}'] {
        transform: translateX(-100% * $index);
      }
    }
  }

  &__slide {
    flex: 0 0 100%;
    min-width: 0;
  }

  &__arrow {
    @include icon-button(52px);
---
  color: color('text');
  box-shadow: 0 30px 80px rgba(color('black'), 0.6);
  overflow: hidden;

  &[open] {
    display: flex;
    animation: modal-in 220ms ease both;
  }

  &::backdrop {
    background-color: color('backdrop');
    backdrop-filter: blur(3px);
    animation: backdrop-in 220ms ease both;
  }

  &.is-closing {
    animation: modal-out 180ms ease both;

    &::backdrop {
      animation: backdrop-out 180ms ease both;
    }
  }

  &__panel {
    position: relative;
    display: grid;
    justify-items: start;
    gap: space(3);
    width: 100%;
    padding: space(6) space(5) space(5);
    overflow-y: auto;
  }

  &__close {
    position: absolute;
    top: space(3);
    right: space(3);
    @include icon-button(40px);
    @include focus-ring;
    background-color: transparent;
    color: color('text-muted');
---
  text-transform: uppercase;
  color: color('accent');
}

@mixin reduced-motion {
  @media (prefers-reduced-motion: reduce) {
    @content;
  }
}
