2	 * Pure layout math shared by the behavior modules. Nothing here touches the
3	 * DOM, so it is unit tested directly in tests/geometry.test.mjs.
4	 */
5	
6	const EDGE_TOLERANCE = 1;
7	const MIN_SCROLL_MS = 400;
8	const MAX_SCROLL_MS = 900;
9	const MS_PER_PIXEL = 0.25;
10	
11	function clamp(value, min, max) {
12	  return Math.min(Math.max(value, min), max);
13	}
14	
15	/**
16	 * Index of the section lying directly under the navbar's bottom edge.
17	 *
18	 * @param {{top: number}[]} rects section tops in viewport coordinates, in page order
19	 * @param {number} navBottom the navbar's bottom edge in viewport coordinates
20	 * @param {boolean} atBottom whether the page is scrolled to its end
21	 * @returns {number} the active index, or -1 when there are no sections
22	 */
23	export function activeSectionIndex(rects, navBottom, atBottom) {
24	  if (rects.length === 0) {
25	    return -1;
26	  }
27	  // A short last section can never reach the navbar, so the end of the page
28	  // always belongs to it.
29	  if (atBottom) {
30	    return rects.length - 1;
31	  }
32	  // The last section whose top has reached the edge wins. Searching from the
33	  // end matters at a boundary: the previous section's bottom and the next
34	  // section's top are both within tolerance there, and the next one is current.
35	  const edge = navBottom + EDGE_TOLERANCE;
36	  for (let index = rects.length - 1; index > 0; index -= 1) {
37	    if (rects[index].top <= edge) {
38	      return index;
39	    }
40	  }
41	  return 0;
42	}
