44	/**
45	 * Scroll position that lands a section's top flush under the small navbar.
46	 */
47	export function scrollTargetY(sectionTop, smallNavHeight, maxScroll) {
48	  return clamp(sectionTop - smallNavHeight, 0, maxScroll);
49	}
