51	/**
52	 * Animation length for a scroll of the given distance: longer trips take
53	 * longer, within fixed bounds so no trip feels instant or sluggish.
54	 */
55	export function scrollDuration(distance) {
56	  return clamp(Math.abs(distance) * MS_PER_PIXEL, MIN_SCROLL_MS, MAX_SCROLL_MS);
