2567	+/*
2568	+ * Pure layout math shared by the behavior modules. Nothing here touches the
2569	+ * DOM, so it is unit tested directly in tests/geometry.test.mjs.
2570	+ */
2571	+
2572	+const EDGE_TOLERANCE = 1;
2573	+const MIN_SCROLL_MS = 400;
2574	+const MAX_SCROLL_MS = 900;
2575	+const MS_PER_PIXEL = 0.25;
2576	+
2577	+function clamp(value, min, max) {
2578	+  return Math.min(Math.max(value, min), max);
2579	+}
2580	+
2581	+/**
2582	+ * Index of the section lying directly under the navbar's bottom edge.
2583	+ *
2584	+ * @param {{top: number}[]} rects section tops in viewport coordinates, in page order
2585	+ * @param {number} navBottom the navbar's bottom edge in viewport coordinates
2586	+ * @param {boolean} atBottom whether the page is scrolled to its end
2587	+ * @returns {number} the active index, or -1 when there are no sections
2588	+ */
2589	+export function activeSectionIndex(rects, navBottom, atBottom) {
2590	+  if (rects.length === 0) {
2591	+    return -1;
2592	+  }
2593	+  // A short last section can never reach the navbar, so the end of the page
2594	+  // always belongs to it.
2595	+  if (atBottom) {
2596	+    return rects.length - 1;
2597	+  }
2598	+  // The last section whose top has reached the edge wins. Searching from the
2599	+  // end matters at a boundary: the previous section's bottom and the next
2600	+  // section's top are both within tolerance there, and the next one is current.
2601	+  const edge = navBottom + EDGE_TOLERANCE;
2602	+  for (let index = rects.length - 1; index > 0; index -= 1) {
2603	+    if (rects[index].top <= edge) {
2604	+      return index;
2605	+    }
2606	+  }
2607	+  return 0;
2608	+}
