15	  ], { stdio: 'ignore' });
16	
17	  let target;
18	  for (let i = 0; i < 50; i += 1) {
19	    try {
20	      const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
21	      target = list.find((t) => t.type === 'page');
22	      if (target) break;
23	    } catch (e) { /* not up yet */ }
24	    await new Promise((r) => setTimeout(r, 200));
25	  }
26	  if (!target) throw new Error('Chrome did not start');
27	
28	  const ws = new WebSocket(target.webSocketDebuggerUrl);
29	  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
30	  let id = 0;
31	  const pending = new Map();
32	  const events = [];
33	  ws.onmessage = (msg) => {
34	    const data = JSON.parse(msg.data);
35	    if (data.id && pending.has(data.id)) {
36	      const { resolve, reject } = pending.get(data.id);
37	      pending.delete(data.id);
38	      if (data.error) reject(new Error(JSON.stringify(data.error))); else resolve(data.result);
39	    } else if (data.method) {
40	      events.push(data);
41	    }
42	  };
43	  const send = (method, params = {}) => new Promise((resolve, reject) => {
44	    id += 1;
45	    pending.set(id, { resolve, reject });
46	    ws.send(JSON.stringify({ id, method, params }));
47	  });
48	
49	  await send('Page.enable');
50	  await send('Runtime.enable');
51	  await send('Network.enable');
52	  await send('Log.enable');
53	
54	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
