71	      await sleep(1200);
72	    },
73	    async eval(expression) {
74	      const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
75	      if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
76	      return r.result.value;
77	    },
78	    async shot(file) {
