80	      writeFileSync(file, Buffer.from(r.data, 'base64'));
81	    },
82	    async key(key, code, keyCode) {
83	      await send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: keyCode });
