    28	  const unlock = () => {
    29	    locked = false;
    30	    window.clearTimeout(fallbackTimer);
    31	  };
    32	
    33	  const render = () => {
    34	    track.dataset.index = String(current);
    35	    slides.forEach((slide, index) => {
    36	      // Off-screen slides leave the tab order and the accessibility tree.
    37	      slide.inert = index !== current;
    38	    });
    39	    if (status) {
    40	      status.textContent = `Slide ${current + 1} of ${slides.length}`;
    41	    }
    42	  };
