    // elements extending past viewport horizontally
    const over = [];
    document.querySelectorAll('body *').forEach((el) => {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) return;
      if (el.closest('.carousel__track') && !el.matches('.carousel__track')) return;
      if (el.closest('dialog')) return;
      if (r.right > vw + 0.5 || r.left < -0.5) over.push(el.tagName + '.' + el.className + ' L' + Math.round(r.left) + ' R' + Math.round(r.right));
    });
    res.overflowing = over.slice(0, 15);
    res.sections = ['home','about','skills','projects','reel','contact'].map((id) => { const s = document.getElementById(id); const r = s.getBoundingClientRect(); return { id, top: Math.round(r.top + scrollY), h: Math.round(r.height), w: Math.round(r.width) }; });
    const nav = document.querySelector('[data-navbar]');
    res.nav = { h: nav.getBoundingClientRect().height, pos: getComputedStyle(nav).position, linkFont: getComputedStyle(document.querySelector('[data-nav-link]')).fontSize, logoFont: getComputedStyle(document.querySelector('.navbar__logo')).fontSize };
    const links = [...document.querySelectorAll('.navbar__links li')].map((li) => { const r = li.getBoundingClientRect(); return [Math.round(r.left), Math.round(r.right), Math.round(r.top)]; });
    res.navLinks = links;
    const logo = document.querySelector('.navbar__logo').getBoundingClientRect();
    res.logo = [Math.round(logo.left), Math.round(logo.right)];
    res.imgs = [...document.images].map((i) => ({ src: i.currentSrc.split('/').pop(), nat: i.naturalWidth + 'x' + i.naturalHeight, box: Math.round(i.getBoundingClientRect().width) + 'x' + Math.round(i.getBoundingClientRect().height), complete: i.complete, fit: getComputedStyle(i).objectFit }));
    res.skillsCols = getComputedStyle(document.querySelector('.skills')).gridTemplateColumns;
    res.aboutCols = getComputedStyle(document.querySelector('.about')).gridTemplateColumns;
    res.cardCols = getComputedStyle(document.querySelector('.project-card')).gridTemplateColumns;
    res.styleAttrs = [...document.querySelectorAll('[style]')].map((e) => e.tagName + '.' + e.className + ':' + e.getAttribute('style'));
    res.inlineScripts = [...document.scripts].filter((s) => !s.src).length;
    res.tables = document.querySelectorAll('table').length;
    // hero centering
    const hero = document.getElementById('home').getBoundingClientRect();
    const hc = document.querySelector('.hero__content').getBoundingClientRect();
    const cue = document.querySelector('.hero__cue').getBoundingClientRect();
    res.hero = { heroH: hero.height, contentTop: hc.top, contentBottom: hc.bottom, contentCenterX: (hc.left + hc.right) / 2, viewportCenterX: vw / 2, cueTop: cue.top, cueBottom: cue.bottom, gapContentCue: cue.top - hc.bottom };
    return res;
  })()`);
