    const bad = []; let multi = 0; let notFixed = 0; let steps = 0;
    const ys = [];
    for (let y = 0; y <= max; y += 9) ys.push(y);
    ys.push(max);
    for (let y = max; y >= 0; y -= 13) ys.push(y);
    ys.push(0);
    for (const y of ys) {
      scrollTo(0, y); await raf(); steps++;
      const nb = nav.getBoundingClientRect();
      if (Math.abs(nb.top) > 0.5) notFixed++;
      const act = links.map((l, i) => l.classList.contains('is-active') ? i : -1).filter((i) => i >= 0);
      if (act.length !== 1) { multi++; continue; }
      let exp = 0;
      secs.forEach((s, i) => { if (s.getBoundingClientRect().top <= nb.bottom + 1) exp = i; });
      const atBottom = scrollY + innerHeight >= document.documentElement.scrollHeight - 2;
      if (atBottom) exp = secs.length - 1;
      if (exp !== act[0]) bad.push({ y: Math.round(scrollY), navBottom: nb.bottom, act: links[act[0]].textContent, exp: links[exp].textContent });
    }
    return { steps, max, multi, notFixed, badCount: bad.length, bad: bad.slice(0, 8) };
  })()`);
  console.log('sweep', JSON.stringify(sweep));

