    // middle of tall sections
    for (const id of ['home','about','skills','projects','reel']) { const s = document.getElementById(id); scrollTo(0, s.offsetTop + s.offsetHeight / 2 - 64); await wait(60); out.push('mid-' + id + '=' + active()); }
    return out;
  })()`);
  console.log('bounds', bounds.join('  '));

  // Navbar resize
  const resize = await b.eval(`(async () => {
    const wait = (ms) => new Promise((r) => setTimeout(r, ms));
    const nav = document.querySelector('[data-navbar]');
    const m = () => ({ y: scrollY, h: +nav.getBoundingClientRect().height.toFixed(1), link: getComputedStyle(document.querySelector('[data-nav-link]')).fontSize, logo: getComputedStyle(document.querySelector('.navbar__logo')).fontSize, bg: getComputedStyle(nav).backgroundColor });
    const out = [];
    scrollTo(0, 0); await wait(500); out.push(m());
    scrollTo(0, 40); await wait(500); out.push(m());
    scrollTo(0, 41); await wait(80); out.push(m()); await wait(500); out.push(m());
    scrollTo(0, 3000); await wait(500); out.push(m());
    scrollTo(0, 0); await wait(500); out.push(m());
    return out;
  })()`);
  console.log('resize', JSON.stringify(resize));

  // Smooth scroll clicks
  await b.eval('scrollTo(0,0)'); await b.sleep(500);
  for (const name of ['About','Skills','Projects','Reel','Contact','Home','Contact','Skills']) {
    const pt = await b.eval(`(() => { const a = [...document.querySelectorAll('[data-nav-link]')].find((l) => l.textContent.trim() === '${name}'); const r = a.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
    const y0 = await b.eval('scrollY');
    await b.eval(`(() => { window.__ys = []; const t0 = performance.now(); const f = () => { window.__ys.push([Math.round(performance.now() - t0), Math.round(scrollY)]); if (performance.now() - t0 < 1500) requestAnimationFrame(f); }; requestAnimationFrame(f); })()`);
    await b.click(pt.x, pt.y);
    await b.sleep(1700);
    const r = await b.eval(`(() => {
      const ys = window.__ys; const distinct = new Set(ys.map((p) => p[1])).size;
      const first = ys.find((p) => p[1] !== ${y0}); const lastMove = [...ys].reverse().find((p, i, a) => a[i + 1] && a[i + 1][1] !== p[1]);
      const id = '${name}'.toLowerCase(); const sec = document.getElementById(id);
      const nav = document.querySelector('[data-navbar]').getBoundingClientRect();
      const head = sec.querySelector('h1, h2').getBoundingClientRect();
      const label = sec.querySelector('.section-head__label, .hero__eyebrow').getBoundingClientRect();
      return { distinctPositions: distinct, startedMs: first && first[0], endedMs: lastMove && lastMove[0], scrollY, secTopMinusNavBottom: +(sec.getBoundingClientRect().top - nav.bottom).toFixed(1), labelTop: Math.round(label.top), headingTop: Math.round(head.top), headingBottom: Math.round(head.bottom), navBottom: nav.bottom, innerHeight, active: [...document.querySelectorAll('[data-nav-link].is-active')].map((l) => l.textContent).join('|'), hash: location.hash };
    })()`);
    console.log('click', name, 'from', y0, JSON.stringify(r));
  }
  // other data-scroll links: logo, hero button, cue
  for (const sel of ['.hero .btn', '.hero__cue', '.navbar__logo']) {
    if (sel !== '.navbar__logo') { await b.eval('scrollTo(0,0)'); await b.sleep(600); }
    const pt = await b.eval(`(() => { const r = document.querySelector('${sel}').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
    await b.click(pt.x, pt.y); await b.sleep(200); const mid = await b.eval('scrollY'); await b.sleep(1300);
    console.log('extra', sel, 'mid', mid, 'end', await b.eval('scrollY'), await b.eval(`[...document.querySelectorAll('[data-nav-link].is-active')].map((l) => l.textContent).join('|')`));
  }
}
await b.close();
