  console.log('escape', JSON.stringify(midClose), JSON.stringify(await b.eval(`({ open: !!document.querySelector('dialog[open]'), locked: document.documentElement.classList.contains('is-scroll-locked'), focus: document.activeElement.tagName + '.' + document.activeElement.className + ':' + (document.activeElement.dataset.modalOpen || ''), y: scrollY })`)));
  // close via X
