  console.log('backdrop close', JSON.stringify(await b.eval(`({ open: !!document.querySelector('dialog[open]'), locked: document.documentElement.classList.contains('is-scroll-locked') })`)));
  // click inside panel must not close
  await b.click(ob.x, ob.y); await b.sleep(500); const d = await center('dialog[open] .modal__title'); await b.click(d.x, d.y); await b.sleep(500);
  console.log('click inside keeps open:', await b.eval(`!!document.querySelector('dialog[open]')`));
  // double Escape fast, then reopen
  await b.key('Escape','Escape',27); await b.sleep(30); await b.key('Escape','Escape',27); await b.sleep(600);
  console.log('double escape', JSON.stringify(await b.eval(`({ open: !!document.querySelector('dialog[open]'), locked: document.documentElement.classList.contains('is-scroll-locked') })`)));
  await b.click(ob.x, ob.y); await b.sleep(500); console.log('reopen works:', await b.eval(`!!document.querySelector('dialog[open]')`));
  await b.key('Escape','Escape',27); await b.sleep(600);
  // all three modals openable and sized
  for (let i = 0; i < 3; i++) {
    const r = await b.eval(`(async () => { const d = document.querySelectorAll('dialog.modal')[${i}]; d.showModal(); await new Promise((r) => setTimeout(r, 300)); const bx = d.getBoundingClientRect(); const p = d.querySelector('.modal__panel'); const out = { id: d.id, h: Math.round(bx.height), top: Math.round(bx.top), bottom: Math.round(bx.bottom), panelScrolls: p.scrollHeight > p.clientHeight }; d.close(); return out; })()`);
    console.log('modal', JSON.stringify(r));
  }
}
await b.close();
