  console.log('tab sequence', foci.join(' | '));
  await b.key('Escape', 'Escape', 27); await b.sleep(80); const midClose = await b.eval(`({ open: !!document.querySelector('dialog[open]'), closing: !!document.querySelector('dialog.is-closing') })`); await b.sleep(500);
  console.log('escape', JSON.stringify(midClose), JSON.stringify(await mstate()));
  await b.click(ob.x, ob.y); await b.sleep(500); const x = await center('dialog[open] [data-modal-close]'); await b.click(x.x, x.y); await b.sleep(500);
  console.log('X close', JSON.stringify(await mstate()));
  await b.click(ob.x, ob.y); await b.sleep(500); await b.click(15, 15); await b.sleep(500);
  console.log('backdrop close', JSON.stringify(await mstate()));
  await b.click(ob.x, ob.y); await b.sleep(500); const d = await center('dialog[open] .modal__title'); await b.click(d.x, d.y); await b.sleep(500);
  console.log('click inside keeps open:', JSON.stringify(await mstate()));
  await b.key('Escape', 'Escape', 27); await b.sleep(30); await b.key('Escape', 'Escape', 27); await b.sleep(600);
  console.log('double escape', JSON.stringify(await mstate()));
  await b.click(ob.x, ob.y); await b.sleep(500); console.log('reopen works:', JSON.stringify(await mstate()));
  await b.key('Escape', 'Escape', 27); await b.sleep(600);
  for (let i = 0; i < 3; i++) {
    const r = await b.eval(`(async () => { const d = document.querySelectorAll('dialog.modal')[${i}]; d.showModal(); await new Promise((r) => setTimeout(r, 300)); const bx = d.getBoundingClientRect(); const p = d.querySelector('.modal__panel'); const out = { id: d.id, h: Math.round(bx.height), top: Math.round(bx.top), bottom: Math.round(bx.bottom), panelScrolls: p.scrollHeight > p.clientHeight }; d.close(); return out; })()`);
    console.log('modal', JSON.stringify(r));
  }
}
await b.close();
"}

