Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp1\39c2764e-f378-4265-ba09-eaeed14656e2\scratchpad\adv-review\t4_misc.mjs", "content": "import { launch } from '../cdp.mjs';
const URL = 'http://127.0.0.1:8137/cs409-mp1/';
const b = await launch(9374);
const sizes = [[1920, 1080], [1366, 768], [1280, 720], [1024, 768], [768, 1024]];
for (const [w, h] of sizes) {
  await b.size(w, h); await b.goto(URL);
  for (const id of ['about', 'skills', 'projects', 'reel', 'contact']) {
    await b.eval(`scrollTo(0, Math.min(document.getElementById('${id}').offsetTop - 64, document.documentElement.scrollHeight - innerHeight))`);
    await b.sleep(500);
    await b.shot(`./sec_${w}x${h}_${id}.png`);
  }
}

// Modal: wheel and PageDown only (no Space, which activates the focused close button)
await b.size(1366, 768); await b.goto(URL);
await b.eval(`scrollTo(0, document.getElementById('projects').offsetTop - 64)`); await b.sleep(600);
const ob = await b.eval(`(() => { const r = document.querySelector('[data-modal-open]').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
await b.click(ob.x, ob.y); await b.sleep(500);
const y0 = await b.eval('scrollY');
await b.wheel(50, 700, 800); await b.sleep(400);
await b.wheel(683, 400, 800); await b.sleep(400);
await b.key('PageDown', 'PageDown', 34); await b.sleep(400);
await b.key('End', 'End', 35); await b.sleep(400);
console.log('modal scroll lock: y before', y0, 'after', await b.eval('scrollY'), 'open', await b.eval(`!!document.querySelector('dialog[open]')`));
await b.key('Escape', 'Escape', 27); await b.sleep(500);

// Icons render? (FontAwesome glyph check)
console.log('icons', JSON.stringify(await b.eval(`(async () => { await document.fonts.ready; return [...document.querySelectorAll('i[class*="fa-"]')].map((i) => { const cs = getComputedStyle(i, '::before'); return i.className + ' => ' + cs.fontFamily.slice(0, 28) + ' ' + cs.fontWeight + ' ' + JSON.stringify(cs.content) + ' w' + Math.round(i.getBoundingClientRect().width); }); })()`), null, 1));
console.log('fonts', JSON.stringify(await b.eval(`[...document.fonts].filter((f) => f.status === 'loaded').map((f) => f.family + ' ' + f.weight)`)));

// Video
console.log('video', JSON.stringify(await b.eval(`(async () => { const v = document.querySelector('video'); v.muted = true; try { await v.play(); } catch (e) { return 'play failed ' + e; } await new Promise((r) => setTimeout(r, 1500)); const o = { duration: v.duration, vw: v.videoWidth, vh: v.videoHeight, t: v.currentTime, box: v.getBoundingClientRect().width + 'x' + v.getBoundingClientRect().height, controls: v.controls, hasAudio: v.mozHasAudio ?? v.webkitAudioDecodedByteCount, error: v.error && v.error.code }; v.pause(); return o; })()`)));

// Fixed background check
console.log('hero bg', JSON.stringify(await b.eval(`(() => { const cs = getComputedStyle(document.getElementById('home')); return { attachment: cs.backgroundAttachment, size: cs.backgroundSize, image: cs.backgroundImage.slice(0, 60), transform: cs.transform, filter: cs.filter, willChange: cs.willChange }; })()`)));

// Deep link load
await b.goto(URL + '#reel'); await b.sleep(500);
console.log('deep link #reel', JSON.stringify(await b.eval(`({ y: scrollY, reelTop: document.getElementById('reel').getBoundingClientRect().top, navBottom: document.querySelector('[data-navbar]').getBoundingClientRect().bottom, active: [...document.querySelectorAll('[data-nav-link].is-active')].map((l) => l.textContent).join('|'), navClass: document.querySelector('[data-navbar]').className })`)));

// Narrow widths outside the graded list
for (const w of [900, 800, 720, 699, 600, 480, 414, 375, 320]) {
  await b.size(w, 800); await b.goto(URL);
  const r = await b.eval(`(() => { const de = document.documentElement; const links = [...document.querySelectorAll('.navbar__links li')].map((li) => li.getBoundingClientRect()); const logo = document.querySelector('.navbar__logo').getBoundingClientRect(); return { w: ${w}, cw: de.clientWidth, sw: de.scrollWidth, navLastRight: Math.round(links[links.length - 1].right), navFirstLeft: Math.round(links[0].left), logoRight: Math.round(logo.right), oneRow: new Set(links.map((l) => Math.round(l.top))).size === 1, skills: getComputedStyle(document.querySelector('.skills')).gridTemplateColumns }; })()`);
  console.log('narrow', JSON.stringify(r));
  if (w === 375 || w === 600) await b.shot(`./narrow_${w}.png`);
}

// Height change keeps hero centered
await b.size(1366, 500); await b.goto(URL);
console.log('hero @1366x500', JSON.stringify(await b.eval(`(() => { const hero = document.getElementById('home').getBoundingClientRect(); const c = document.querySelector('.hero__content').getBoundingClientRect(); const cue = document.querySelector('.hero__cue').getBoundingClientRect(); const btn = document.querySelector('.hero .btn').getBoundingClientRect(); return { heroH: hero.height, contentTop: c.top, contentBottom: c.bottom, navBottom: 96, cueTop: cue.top, btnBottom: btn.bottom }; })()`)));
await b.shot('./hero_1366x500.png');

const evs = b.events.filter((e) => ['Runtime.consoleAPICalled', 'Runtime.exceptionThrown', 'Log.entryAdded'].includes(e.method));
console.log('console/log events', evs.length, JSON.stringify(evs.map((e) => JSON.stringify(e.params).slice(0, 300))));
const failed = b.events.filter((e) => e.method === 'Network.loadingFailed' && !e.params.canceled);
console.log('non-cancel network failures', failed.length);
const bad = b.events.filter((e) => e.method === 'Network.responseReceived' && e.params.response.status >= 400).map((e) => e.params.response.status + ' ' + e.params.response.url);
console.log('4xx/5xx', JSON.stringify(bad));
await b.close();
"}

