Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp1\39c2764e-f378-4265-ba09-eaeed14656e2\scratchpad\adv-review\t5_edge.mjs", "content": "import { launch } from '../cdp.mjs';
const URL = 'http://127.0.0.1:8137/cs409-mp1/';
const b = await launch(9375);
const active = () => b.eval(`[...document.querySelectorAll('[data-nav-link].is-active')].map((l) => l.textContent).join('|')`);
const clickLink = async (name) => {
  const pt = await b.eval(`(() => { const a = [...document.querySelectorAll('[data-nav-link]')].find((l) => l.textContent.trim() === '${name}'); const r = a.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
  await b.click(pt.x, pt.y);
};

// 0. OS-level reduced motion as seen by this Chrome
await b.size(1366, 768); await b.goto(URL);
console.log('machine prefers-reduced-motion:', await b.eval(`matchMedia('(prefers-reduced-motion: reduce)').matches`));

// 1. Reel landing: is the whole video inside the viewport after clicking Reel?
for (const [w, h] of [[1920, 1080], [1366, 768], [1280, 720], [1024, 768], [768, 1024]]) {
  await b.size(w, h); await b.goto(URL);
  await clickLink('Reel'); await b.sleep(1500);
  console.log('reel landing', `${w}x${h}`, JSON.stringify(await b.eval(`(() => { const v = document.querySelector('video').getBoundingClientRect(); return { videoTop: Math.round(v.top), videoBottom: Math.round(v.bottom), innerHeight, clippedPx: Math.max(0, Math.round(v.bottom - innerHeight)), videoBox: Math.round(v.width) + 'x' + Math.round(v.height) }; })()`)));
  await clickLink('Projects'); await b.sleep(1500);
  console.log('projects landing', `${w}x${h}`, JSON.stringify(await b.eval(`(() => { const c = document.querySelector('.carousel').getBoundingClientRect(); return { carouselBottom: Math.round(c.bottom), innerHeight }; })()`)));
  await clickLink('Skills'); await b.sleep(1500);
  console.log('skills landing', `${w}x${h}`, JSON.stringify(await b.eval(`(() => { const c = document.querySelector('.skills').getBoundingClientRect(); return { gridBottom: Math.round(c.bottom), innerHeight }; })()`)));
  await clickLink('About'); await b.sleep(1500);
  console.log('about landing', `${w}x${h}`, JSON.stringify(await b.eval(`(() => { const c = document.querySelector('.about').getBoundingClientRect(); return { aboutBottom: Math.round(c.bottom), innerHeight }; })()`)));
}

// 2. Fractional device pixel ratios (Windows display scaling 125% / 150%)
for (const dpr of [1.25, 1.5, 1.1]) {
  const cssW = Math.round(1920 / dpr); const cssH = Math.round(1080 / dpr);
  await b.send('Emulation.setDeviceMetricsOverride', { width: cssW, height: cssH, deviceScaleFactor: dpr, mobile: false });
  await b.goto(URL);
  const res = [];
  for (const name of ['About', 'Skills', 'Projects', 'Reel', 'Contact', 'Home', 'Reel', 'About']) {
    await clickLink(name); await b.sleep(1400);
    const a = await active(); const y = await b.eval('scrollY');
    res.push(`${name}->${a}@${y}${a === name ? '' : ' MISMATCH'}`);
  }
  console.log(`dpr ${dpr} (${cssW}x${cssH})`, res.join('  '));
  console.log('  bottom:', JSON.stringify(await b.eval(`(async () => { scrollTo(0, 1e9); await new Promise((r) => setTimeout(r, 300)); return { y: scrollY, ih: innerHeight, sh: document.documentElement.scrollHeight, active: [...document.querySelectorAll('[data-nav-link].is-active')].map((l) => l.textContent).join('|'), sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }; })()`)));
}

// 3. Click a second link mid-animation
await b.size(1366, 768); await b.goto(URL);
await clickLink('Contact'); await b.sleep(250); await clickLink('About'); await b.sleep(1500);
console.log('mid-animation re-click ->', await active(), await b.eval('scrollY'));
// wheel interrupt
await clickLink('Contact'); await b.sleep(200); await b.wheel(600, 400, -100); await b.sleep(1200);
console.log('wheel interrupt -> y', await b.eval('scrollY'), await active());

// 4. Carousel wrap direction: sample transform while going 3 -> 1
await b.eval(`scrollTo(0, document.getElementById('projects').offsetTop - 64)`); await b.sleep(600);
const next = await b.eval(`(() => { const r = document.querySelector('[data-carousel-next]').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
await b.click(next.x, next.y); await b.sleep(600); await b.click(next.x, next.y); await b.sleep(600);
await b.click(next.x, next.y); await b.sleep(200);
console.log('wrap 3->1 mid-transition transform:', await b.eval(`getComputedStyle(document.querySelector('[data-carousel-track]')).transform`), 'viewport width', await b.eval(`document.querySelector('.carousel__viewport').getBoundingClientRect().width`));
