import http from 'node:http';
import { createReadStream, statSync, existsSync, writeFileSync } from 'node:fs';
import { join, extname } from 'node:path';
import { launch } from '../cdp.mjs';

const ROOT = 'C:/Users/User/Dropbox/UIUC/2026 Fall/CS 409 Art of Web Programming/mp1/build';
const TYPES = { '.html': 'text/html', '.js': 'text/javascript', '.mp4': 'video/mp4', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml', '.map': 'application/json' };
const server = http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]).replace(/^\/cs409-mp1/, '');
  if (p === '' || p === '/') p = '/index.html';
  const file = join(ROOT, p);
  if (p.includes('..') || !existsSync(file)) { res.writeHead(404); res.end(); return; }
  const size = statSync(file).size;
  const type = TYPES[extname(file)] || 'application/octet-stream';
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.range || '');
  if (m) {
    const start = m[1] ? +m[1] : 0; const end = m[2] ? +m[2] : size - 1;
    res.writeHead(206, { 'Content-Type': type, 'Accept-Ranges': 'bytes', 'Content-Range': `bytes ${start}-${end}/${size}`, 'Content-Length': end - start + 1 });
    createReadStream(file, { start, end }).pipe(res);
  } else {
    res.writeHead(200, { 'Content-Type': type, 'Accept-Ranges': 'bytes', 'Content-Length': size });
    createReadStream(file).pipe(res);
  }
});
await new Promise((r) => server.listen(8139, '127.0.0.1', r));
