await b.eval(`(() => { window.__ys = new Set(); window.__hs = new Set(); const nav = document.querySelector('[data-navbar]'); const tick = () => { window.__ys.add(Math.round(scrollY)); window.__hs.add(Math.round(nav.getBoundingClientRect().height)); requestAnimationFrame(tick); }; tick(); })()`);
await b.click(link.x, link.y);
await b.sleep(900);
const rm = await b.eval(`({ positions: window.__ys.size, navHeights: [...window.__hs], active: document.querySelector('[data-nav-link].is-active, [data-nav-link][aria-current]')?.textContent.trim(), top: Math.round(document.getElementById('projects').getBoundingClientRect().top) })`);
